using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using PokemonMvc.Data;namespace PokemonMvc.Controllers;[ApiController][Route("api/catalog")]public class CatalogController(PokemonContext db):ControllerBase{[HttpGet("cards")]public async Task<IActionResult> Cards()=>Ok(await db.Cards.AsNoTracking().ToListAsync());[HttpGet("cards/{id:int}")]public async Task<IActionResult> Card(int id){var c=await db.Cards.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);return c==null?NotFound():Ok(c);}[HttpGet("sets")]public async Task<IActionResult> Sets()=>Ok(await db.Cards.Select(x=>x.SetName).Distinct().OrderBy(x=>x).ToListAsync());}